use aap::caps::state_read;

struct Node;

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let raw = state_read::get("urls").unwrap_or_default();
        let urls: Vec<String> = raw
            .split(|c: char| c == '\n' || c == ',' || c.is_whitespace())
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect();
        // Contract: present(urls). With no subscriptions there is no valid
        // output to produce, so trap rather than emit an empty list.
        if urls.is_empty() {
            panic!("no subscriptions found in store");
        }
        SubscriptionList { urls }
    }
}

export!(Node);
