use aap::caps::state_read;

struct Node;

fn parse(raw: &str) -> Vec<String> {
    raw.split(|c: char| {
        c == '\n' || c == ',' || c == '"' || c == '[' || c == ']' || c.is_whitespace()
    })
    .map(|s| s.trim())
    .filter(|s| !s.is_empty())
    .map(|s| s.to_string())
    .collect()
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in ["urls", "subscriptions", "subscription"] {
            if let Some(raw) = state_read::get(key) {
                urls = parse(&raw);
                if !urls.is_empty() {
                    break;
                }
            }
        }
        SubscriptionList { urls }
    }
}

export!(Node);
